import 'package:flutter/material.dart'; import 'dashboard_screen.dart'; import 'plantel_cadastro_screen.dart'; import '../database/db_helper.dart';
class NavigationScreen extends StatefulWidget{const NavigationScreen({super.key});@override State<NavigationScreen>createState()=>_NavigationScreenState();}
class _NavigationScreenState extends State<NavigationScreen>{int i=0;@override Widget build(BuildContext c){final pages=[const DashboardScreen(),_Plantel(),const Center(child:Text('Reprodução — módulo profissional em expansão')),const Center(child:Text('Genealogia / Retrocruzamento')),const Center(child:Text('Relatórios'))];return Scaffold(body:pages[i],bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(x)=>setState(()=>i=x),destinations:const[NavigationDestination(icon:Icon(Icons.dashboard),label:'Início'),NavigationDestination(icon:Icon(Icons.pets),label:'Plantel'),NavigationDestination(icon:Icon(Icons.favorite),label:'Reprodução'),NavigationDestination(icon:Icon(Icons.account_tree),label:'Genealogia'),NavigationDestination(icon:Icon(Icons.assessment),label:'Relatórios')]));}}
class _Plantel extends StatefulWidget{const _Plantel();@override State<_Plantel>createState()=>_PlantelState();}class _PlantelState extends State<_Plantel>{@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Plantel')),body:FutureBuilder(future:DbHelper.instance.aves(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final a=s.data!;return ListView.builder(itemCount:a.length,itemBuilder:(c,i)=>ListTile(title:Text(a[i].nome??'Sem nome — ${a[i].clubeSigla}-${a[i].anilha}'),subtitle:Text('${a[i].sexo=='M'?'Macho':'Fêmea'} • ${a[i].raca??'Raça não definida'} • Gaiola ${a[i].numeroGaiola??'-'}'));}),floatingActionButton:FloatingActionButton(onPressed:()async{await Navigator.push(c,MaterialPageRoute(builder:(_)=>const PlantelCadastroScreen()));setState((){});},child:const Icon(Icons.add)));}
